#!/usr/bin/env python3
"""Generate include/vpad.h: IG_VPAD_n declares n placeholder virtuals.

Usage: python3 tools/gen_vpad.py [MAX]   (default 192)
"""
import sys
from pathlib import Path

MAX = int(sys.argv[1]) if len(sys.argv) > 1 else 192

out = [
    "#ifndef VPAD_H",
    "#define VPAD_H",
    "",
    "/* Generated by tools/gen_vpad.py: IG_VPAD_n declares n placeholder virtuals, so the next virtual sits",
    "   in slot n (vtable offset 8 + 4n). For calling game virtuals that aren't modelled yet:",
    "     class beModelCtrlV { public: IG_VPAD_37 virtual void entryRam(beBaseInfoRam*); };  // +0x9C */",
    "",
]
for n in range(MAX + 1):
    out.append(f"#define IG_VPAD_{n} " + " ".join(f"virtual void _v{i}();" for i in range(n)))
out += ["", "#endif /* VPAD_H */", ""]
Path(__file__).resolve().parent.parent.joinpath("include/vpad.h").write_text("\n".join(out))
